def transform(g):
    blocks=[g[i*3:(i+1)*3] for i in range(len(g)//3)]
    base=blocks[0]; others=blocks[1:]
    order=sorted(range(len(others)), key=lambda i:(sum(v!=0 for r in others[i] for v in r), -i))
    out=[row[:] for row in base]
    for r in range(3):
        for c in range(len(base[0])):
            if out[r][c]==0:
                for i in order:
                    if others[i][r][c]!=0:
                        out[r][c]=others[i][r][c]; break
    return out
